INSERT INTO `plantillas_reportes` VALUES (1,'constancia_culminacion','Carta de Culminación de Pasantías','Documento oficial de culminación exitosa de pasantías emitido por la Dirección de Telemática.','Constancias','portrait','letter','img/cintillo.png','CARTA DE CULMINACIÓN DE PASANTÍAS PROFESIONALES','Dirección de Telemática / División de Soporte Técnico','<p>Quien suscribe, en su carácter de responsable del área de <strong>{DEPARTAMENTO}</strong>, adscrito a la <strong>División de Soporte Técnico</strong> de la <strong>Dirección de Telemática</strong> del Instituto de Salud Pública del Estado Bolívar, certifica por medio de la presente que el/la ciudadano/a <strong>{NOMBRE_PASANTE}</strong>, titular de la Cédula de Identidad Nro. <strong>{CEDULA_PASANTE}</strong>, ha <strong>culminado satisfactoriamente</strong> sus Pasantías Profesionales en la institución bajo la supervisión del área de <strong>{DEPARTAMENTO}</strong>, durante el período académico <strong>{PERIODO}</strong>, completando una carga horaria total de <strong>{HORAS_ACUMULADAS} horas</strong>, cumpliendo cabalmente con las <strong>{HORAS_META} horas</strong> exigidas por su casa de estudios <strong>{INSTITUCION}</strong>.</p><p>Se expide la presente carta a petición de la parte interesada, en Ciudad Bolívar, Estado Bolívar, con fecha <strong>{FECHA_EMISION}</strong>.</p>','{\"firmante_nombre\":\"{TUTOR_NOMBRE}\",\"firmante_cargo\":\"Jefe de la División de Soporte Técnico de la Dirección de Telemática\",\"antefirma\":\"Atentamente,\",\"institucion\":\"Instituto de Salud Pública del Estado Bolívar\",\"mostrar_sello\":true,\"sello_texto\":\"Sello Oficial\"}','Documento emitido por el Sistema de Gestión de Pasantías (SGP) | Instituto de Salud Pública del Estado Bolívar','{\"{NOMBRE_PASANTE}\":\"Nombre completo del pasante\",\"{CEDULA_PASANTE}\":\"Cédula de identidad (V-...)\",\"{DEPARTAMENTO}\":\"Departamento o área técnica\",\"{INSTITUCION}\":\"Universidad o Instituto educativo\",\"{PERIODO}\":\"Nombre o duración del período\",\"{HORAS_ACUMULADAS}\":\"Horas completadas\",\"{HORAS_META}\":\"Horas requeridas\",\"{FECHA_INICIO}\":\"Fecha de inicio (dd\\/mm\\/aaaa)\",\"{FECHA_FIN}\":\"Fecha de culminación (dd\\/mm\\/aaaa)\",\"{FECHA_EMISION}\":\"Fecha actual de emisión\",\"{NUMERO_CONTROL}\":\"Código único de control correlativo\",\"{TUTOR_NOMBRE}\":\"Nombre del tutor o jefe de división\"}',0,NULL,'2026-10-29 23:20:13','2026-10-29 23:20:13'),(2,'constancia_servicio','Constancia de Pasantía en Curso','Constancia que certifica que el estudiante se encuentra activo realizando pasantías.','Constancias','portrait','letter','img/cintillo.png','CONSTANCIA DE PASANTÍA','Dirección de Telemática / División de Soporte Técnico','<p>Quien suscribe, en su carácter de responsable del área de <strong>{DEPARTAMENTO}</strong>, adscrito a la <strong>División de Soporte Técnico</strong> de la <strong>Dirección de Telemática</strong> del Instituto de Salud Pública del Estado Bolívar, hace constar por medio de la presente que el/la ciudadano/a <strong>{NOMBRE_PASANTE}</strong>, titular de la Cédula de Identidad Nro. <strong>{CEDULA_PASANTE}</strong>, se encuentra realizando pasantías académicas en esta institución bajo la supervisión del área de <strong>{DEPARTAMENTO}</strong>, cumpliendo una carga horaria estimada de <strong>{HORAS_META} horas</strong> correspondiente al período <strong>{PERIODO}</strong>, con fecha de inicio el <strong>{FECHA_INICIO}</strong> y fecha estimada de culminación el <strong>{FECHA_FIN}</strong>.</p><p>Constancia que se expide a solicitud de la parte interesada, en Ciudad Bolívar, a los {FECHA_EMISION}.</p>','{\"firmante_nombre\":\"{TUTOR_NOMBRE}\",\"firmante_cargo\":\"Jefe de la División de Soporte Técnico de la Dirección de Telemática\",\"antefirma\":\"Atentamente,\",\"institucion\":\"Instituto de Salud Pública del Estado Bolívar\",\"mostrar_sello\":true,\"sello_texto\":\"Sello Oficial\"}','Documento emitido por el Sistema de Gestión de Pasantías (SGP) | Instituto de Salud Pública del Estado Bolívar','{\"{NOMBRE_PASANTE}\":\"Nombre completo del pasante\",\"{CEDULA_PASANTE}\":\"Cédula de identidad (V-...)\",\"{DEPARTAMENTO}\":\"Departamento o área técnica\",\"{INSTITUCION}\":\"Universidad o Instituto educativo\",\"{PERIODO}\":\"Nombre o duración del período\",\"{HORAS_META}\":\"Horas requeridas\",\"{FECHA_INICIO}\":\"Fecha de inicio\",\"{FECHA_FIN}\":\"Fecha estimada de fin\",\"{FECHA_EMISION}\":\"Fecha actual de emisión\",\"{NUMERO_CONTROL}\":\"Código de control\",\"{TUTOR_NOMBRE}\":\"Nombre del tutor asignado\"}',0,NULL,'2026-10-29 23:20:13','2026-10-29 23:20:13'),(3,'constancia_egresado','Constancia de Pasantías (Egresados Históricos)','Constancia especial para pasantes que culminaron en períodos académicos cerrados.','Constancias','portrait','letter','img/cintillo.png','CONSTANCIA DE SERVICIO DE PASANTÍA PROFESIONAL','Historial y Respaldo Institucional — Dirección de Telemática','<p>Por medio de la presente, la Dirección de Telemática del Instituto de Salud Pública del Estado Bolívar deja constancia de que el ciudadano/a <strong>{NOMBRE_PASANTE}</strong>, portador de la C.I. <strong>{CEDULA_PASANTE}</strong>, egresado de <strong>{INSTITUCION}</strong>, prestó satisfactoriamente sus servicios de pasantías en esta dependencia en el área de <strong>{DEPARTAMENTO}</strong>, durante un lapso de <strong>{PERIODO}</strong>, cumpliendo una carga horaria de <strong>{HORAS_ACUMULADAS} horas</strong>.</p><p>Se extiende la presente constancia histórica en Ciudad Bolívar, en fecha <strong>{FECHA_EMISION}</strong>.</p>','{\"firmante_nombre\":\"{TUTOR_NOMBRE}\",\"firmante_cargo\":\"Jefe de la División de Soporte Técnico de la Dirección de Telemática\",\"antefirma\":\"Atentamente,\",\"institucion\":\"Instituto de Salud Pública del Estado Bolívar\",\"mostrar_sello\":true,\"sello_texto\":\"Sello Oficial\"}','Registro Histórico SGP | Respaldo Oficial de la Dirección de Telemática','{\"{NOMBRE_PASANTE}\":\"Nombre completo del pasante\",\"{CEDULA_PASANTE}\":\"Cédula de identidad\",\"{DEPARTAMENTO}\":\"Departamento de pasantía\",\"{INSTITUCION}\":\"Institución educativa\",\"{PERIODO}\":\"Duración (ej: 6 Meses \\/ 2024-2025)\",\"{HORAS_ACUMULADAS}\":\"Horas cumplidas\",\"{FECHA_EMISION}\":\"Fecha de expedición\",\"{TUTOR_NOMBRE}\":\"Nombre bajo firma\"}',0,NULL,'2026-10-29 23:20:13','2026-10-29 23:20:13'),(4,'ficha_asistencia_individual','Ficha Personal y Control de Asistencia','Expediente integral con historial de asistencias, tardanzas, faltas y firmas.','Asistencias','portrait','letter','img/cintillo.png','FICHA DE ASISTENCIA Y CONTROL INDIVIDUAL','Expediente Académico y Récord Horario','<p>Reporte oficial de asistencias registradas mediante el sistema biométrico y de kiosco digital para el pasante <strong>{NOMBRE_PASANTE}</strong> (C.I. <strong>{CEDULA_PASANTE}</strong>), adscrito a <strong>{DEPARTAMENTO}</strong> bajo tutoría de <strong>{TUTOR_NOMBRE}</strong>.</p>','{\"firmante_nombre\":\"{TUTOR_NOMBRE}\",\"firmante_cargo\":\"Tutor Institucional Asignado\",\"antefirma\":\"Conforme,\",\"institucion\":\"División de Soporte Técnico \\/ Telemática\",\"mostrar_sello\":true,\"sello_texto\":\"Visto Bueno\"}','Expediente Individual de Asistencias SGP | Sistema Biométrico','{\"{NOMBRE_PASANTE}\":\"Nombre del pasante\",\"{CEDULA_PASANTE}\":\"Cédula del pasante\",\"{DEPARTAMENTO}\":\"Departamento asignado\",\"{TUTOR_NOMBRE}\":\"Tutor institucional\",\"{PERIODO}\":\"Período académico\"}',0,NULL,'2026-10-29 23:20:13','2026-10-29 23:20:13'),(5,'evaluacion_desempeno','Ficha de Evaluación de Desempeño','Evaluación técnica, actitudinal y cuantitativa del pasante con baremo oficial.','Evaluaciones','portrait','letter','img/cintillo.png','EVALUACIÓN DE DESEMPEÑO DEL PASANTE','Dirección de Telemática — Instituto de Salud Pública','<p>Instrumento de evaluación integral de competencias, rendimiento y responsabilidad aplicado al pasante <strong>{NOMBRE_PASANTE}</strong> (C.I. <strong>{CEDULA_PASANTE}</strong>) durante el desarrollo de sus pasantías en <strong>{DEPARTAMENTO}</strong>.</p>','{\"firmante_nombre\":\"{TUTOR_NOMBRE}\",\"firmante_cargo\":\"Tutor Institucional Evaluador\",\"antefirma\":\"Evaluado por,\",\"institucion\":\"Instituto de Salud Pública del Estado Bolívar\",\"mostrar_sello\":true,\"sello_texto\":\"Sello de Evaluación\"}','Ficha de Evaluación SGP | Confidencial Institucional','{\"{NOMBRE_PASANTE}\":\"Nombre del pasante\",\"{CEDULA_PASANTE}\":\"Cédula de identidad\",\"{DEPARTAMENTO}\":\"Área evaluada\",\"{TUTOR_NOMBRE}\":\"Nombre del evaluador\",\"{FECHA_EMISION}\":\"Fecha de evaluación\"}',0,NULL,'2026-10-29 23:20:13','2026-10-29 23:20:13'),(6,'auditoria_bitacora','Comprobante de Auditoría de Bitácora','Certificado forense de trazabilidad de acciones y eventos del sistema.','Auditoría','portrait','letter','img/cintillo.png','COMPROBANTE DE AUDITORÍA Y TRAZABILIDAD TÉCNICA','Bitácora Forense Digital — SGP','<p>El presente documento certifica la autenticidad e integridad del registro de auditoría registrado en el sistema SGP. La acción auditada fue ejecutada conforme a los protocolos institucionales de seguridad informática.</p>','{\"firmante_nombre\":\"SuperAdministrador del Sistema\",\"firmante_cargo\":\"Oficina de Seguridad y Auditoría de Sistemas\",\"antefirma\":\"Certificación Digital,\",\"institucion\":\"Dirección de Telemática\",\"mostrar_sello\":true,\"sello_texto\":\"Sello de Seguridad\"}','Certificado de Auditoría Digital SGP | Trazabilidad Inmutable','{\"{NUMERO_CONTROL}\":\"Número correlativo de auditoría\",\"{FECHA_EMISION}\":\"Fecha y hora exacta del registro\"}',0,NULL,'2026-10-29 23:20:13','2026-10-29 23:20:13');
